prk1 = ['>>>>>>>>>> Теория по теме: Задание 9. Правописание корней <<<<<<<<<<', '', '1.Безударная чередующаяся гласная в корне', '', '1)Гласная в корне зависит от ударения', '', 'ГАР-/ГОР- Без ударения пишется О: загорать, горелый, гореть, пригорелый, горелка, перегорание, обгореть, сгораемость и др.', '', 'Исключения: пригарь, выгарки', '', 'Не являются корнями с чередованием омонимичные корни в словах: горн, горе, горевать, загоревать, огорчать, огорчить, огорчение, огорченный, огорчительный, пригорюниться, горький, горчинка, горчица, горчичник, горчичный.', '', 'КЛАН-/КЛОН- Без ударения пишется О, а под ударением пишем то, что слышим: склоняться, преклонение, наклон, непреклонный, кланяться, раскланяться, откланяться, клонить(ся), наклонение, преклонение, склонение, уклонение, коленопреклонение, коленопреклонённый и др.', '', 'ТВАР-/ТВОР Без ударения пишется О, а под ударением пишем то, что слышим: творить, благотворительный, вытворить, вытворять, натворить, одухотворенный, олицетворять, претворить, претворять, притворяться, растворение, растворимый, сотворение, сотворить, столпотворение, творение, творительный, творить, удовлетворить и др.', '', 'Исключения: утварь.', '', 'Не являются корнями с чередованием омонимичные корни в словах: затворить, затвор, притворить, створка.', '', 'ЗАР-/ЗОР Без ударения пишется А: заря, заревой, зарница, озарение, озарить, зарянка (птица), зарево, лучезарный, зори (мн.ч.), зорька, зоренька, зорюшка и др.', '', 'Не являются корнями с чередованием омонимичные корни в словах: зариться, позариться, взор, надзор, обзор, подзорный, прозорливый; озорной, озорничать, озоровать, озорной, позор, узор', '', 'ПЛАВ-/ПЛОВ-/ПЛЫВ- Без ударения пишется А: плавучий, плавник, поплавок, плавун (трава), плавунец (жук), сплавлять, на плаву.', '', 'Исключения: пловец, пловчиха.', '', '', '2) Гласная в корне зависит от согласных в корне', '', 'ЛАГ-/ЛОЖ- Перед Г пишем А, перед Ж пишем О: излагать(ся), налагать(ся), облагать(ся), полагать(ся), предлагать(ся), прилагать(ся), разлагать(ся), слагать(ся), прилагательное, ложиться, возложить, переложить и др.', '', 'Исключения: полог.', '', 'СКАК (СКАЧ) СКОК (СКОЧ) Безударное А пишется перед К, безударное О - перед Ч: доскакать, заскакать, обскакать, отскакать, перескакать, поскакать, прискакать, скакалка, скакун, выскочить, доскочить, заскочить, наскочить, проскочить и др.', '', 'РАС(Т)-/РОС-РАЩ Перед СТ и Щ пишется А, перед С пишется О: возрасти, дорасти, зарасти, растить, отрастить, возрастать, прорастание, растение, растительный, возраст, возрастной, наращение, взрослеть, заросль, недоросль, поросль, повзрослеть и др.', '', 'Исключения: росток, ростовщик, Ростислав, Ростов, отрасль.', '', '', '3) Гласная в корне зависит от значения', '', 'РАВН-/РОВН-', '', 'РАВН- пишется в словах со значением «равный кому/чему, одинаковый с кем/чем», «сравнение»: выравнять (силы), выравняться (в строю), подравняться (класс команд подравнялся), приравнять, равнять (кого, кого с кем), равняться (что чему, в шеренге, в строю или по первому), сравняться (с кем-то в чем-то, в успехах, в знании), уравнять (в правах); всё равно, наравне (сын трудится наравне с отцом)', '', 'РОВН- пишется в словах со значением «ровный, гладкий, стабильный, прямой, однородный»: ровнять (о крае, линии, плоскости), прировнять (пригладить), уровнять (сделать ровным)', '', 'Исключения: равнина, ровесник, уровень, поровну', '', '', '', 'МАК(Ч)/МОК(Ч)', '', 'МАК- Пишется в словах со значением «погружать в жидкость»: макать, обмакнуть, вымакать, макание и др.', '', 'МОК - Пишется в словах со значением «пропускать жидкость, становиться мокрым»: взмокать, намокать, обмокать, подмокать и др.', '', 'В безударном корне МОЧ пишется О: мочить с разными приставками, моченый.', '', '', '4) Гласная в корне зависит от суффикса', '', 'a) О/А', '', 'Если есть суффикс А после корня, то в корне пишем А, если нет суффикса А, пишем О в корне', 'КОС-/КАС-: касаться, соприкасаться, касание, прикасаться, касательная, касательно, прикасание, коснуться, неукоснительный, прикосновение, соприкоснуться и др.', 'Не являются корнями с чередованием омонимичные корни в словах: кос- (косец, косить, коса (орудие), кос- (косой, искоса, наперекосяк) и кос- (косичка, коса (вид прически))).', '', 'b) Е/И', '', 'Если после корня следует суффикс А, то в корне пишется И', '', 'БЕР-/БИР-: выберу(сь), заберу(сь), наберу(сь), выбирать, избирать, забирать, собирать перебирать, собирательный, избирательный и др.', '', 'БЛЕСК(С, СТ, Щ)/ БЛИСТ: проблеск, блестеть, блестящий, блистать, блистание, блистательный и др.', '', 'ДЕР-/ ДИР-: выдеру, выдерешь, подерусь, продерусь, придерусь, обдирала, удирать, выдирать, выдирание и др.', '', 'МЕР-/ МИР-: замереть, обмереть, умертвить, смертельный, насмерть, вымирать, умирать, вымирание, замирать и др.', '', 'Не являются корнями с чередованием омонимичные корни в словах: мер- со значением «мера, мерка» (примерять) и мир- со значением «мир» (усмирять, примирять)', '', 'ПЕР-/ ПИР-: опереться, взаперти, запереть, отпереть, запирать, опираться, попирание, запирательство и др.', '', 'ТЕР-/ТИР-: тереть, натереть, вытереть, стереть, обтирать, вытирать, утирать, оттирать и др.', '', 'ЖЕГ-/ ЖИГ: выжегший, выжечь, зажечь, выжигание, разжигатель, поджигательство, зажигательный и др.', '', 'СТЕЛ-/СТИЛ: стелить, застелить, выстелить, постелить, расстелить, застилать, выстилать, перестилать и др.', '', 'ЧЕТ(ЧЕС)/ЧИТ: вычесть, чета, вычет, вычитать, предпочитать, считаться, почитать, почитатель, почитание и др.', '', 'Исключения: сочетать, сочетание', '', 'А(Я)/ИМ/ЕМ и А(Я)/ИН: взимать - взять; иметь, имение, имущество, преимущество, имущий, имущественный, преимущественный, неимоверный, внимать, внимание, внимательный, воспринимать, вынимать, донимать, занимать, занимательный, нанимать, обнимать, отнимать, перенимать, понимать, поднимать, предпринимать, предприниматель, наниматель, пронимать, снимать, унимать.', 'К корням с чередованием А(Я)/ИМ/ЕМ и А(Я)/ИН, относятся также:', '']
prk2 = ['ЖИМ/ЖА: выжимать, выжимки, зажимать и др. приставочные от глагола жать', '', 'ЖИН/ЖА: пожинать - сжать', '', 'ПИН/ПЯ: распинать, пинать, пинок, запинаться, препинание - распять, запятая', '', 'МИН/МЯ: вминать, заминать, подминать, приминать, разминаться, уминать - вмять, замять, память, памятовать, памятный, памятник, поминать (и приставочные вспоминать, упоминать, запоминать, напоминать, припоминать), помин, поминовение и др.', '', 'ЧИН/ЧА: начинать, зачинать, зачинатель, начинание, начинающий - начать', '', 'КЛИН/КЛЯ: заклинать, заклинанье, проклинать - заклясть, проклясть, проклятие, заклятие, клятва, заклятый, клясть', '', 'Исключения: выемка, выем, выемщик, выемчатый, выемчатокрылый, жеманиться, формы глагола проклясть (прокляну, проклянешь), помянуть, упомянуть, вспомянуть, выжимки', '', '', '2.Проверяемые гласные в корне', 'Правописание безударных гласных в корнях проверяется подбором слов и форм слова, где эта гласная находится в ударной позиции:', '', 'Горить (гОвор), жара (жАркий) молодой (мОлодость)', '', 'Безударную гласную корня нельзя проверять глаголами несовершенного вида с суффиксом ЫВА(ИВА)', '', 'Например: замолчать, так как мОлча, хотя умАлчивать; выбросить, так брОсить, хоть выбрАсывать и т.д.', '', 'Среди слов с проверяемой гласной часто встречаются корни-омофоны, обычно рядом со словам с таким корнем в скобках указано слово, помогающее понять значение слова.', '', 'Обвевать (веять) - обвивать (вить);', 'Частота (часто) - чистота (чистый);', 'Валы (вал) - вол (вол);', 'Спешите (спешка) - спишите (пишет);', 'Поседеть (сед) - посидеть (сидя);', 'Слепить (лепка) - слипаться (липкий);', 'скрепить (скрепка) - скрипеть (скрип);', 'Разредить (редко) - разрядить (ряд);', 'Посветить (свет) - посвятить (святость);', 'Отворить (затвор) - отварить (варит);', 'Запивать (пить) - запевать (петь);', 'Обижать (обида) - обежать (бег);', 'Примерять (мера) - примирять (мир);', 'Старожил (старый) - сторожил (сторож);', 'развиваться (развитие)- развеваться (веет);', 'полоскать (полощет) - поласкать (ласка);', 'прожевал (жёваный) - проживал (жить);', 'распевать (петь) - распивать (пить);', 'подражать (дразнит) - подрожать (дрожь);', 'умолять (молит) - умалять (мало);', 'окатиться (катит) - окотиться (кот);', 'увидать (видеть) - увядать (вянуть);', 'заплотить (плот) - заплатить (плата).', 'Залезать (залез) - зализать (лижет)', 'Оземь (зЕмли)-озимь (зИмы)', 'Малы (маленький) - молы (мол)', 'Накалить(накал) - наколоть (колет)', 'Пристежные (стёганый) - пристяжные (тяга)', 'Долина (дол)- вдалеке (даль)', 'Кратчайший (краткий) - кротчайший (кроткий)', '', '3.Непроверяемые гласные в корне', '', 'Написание непроверяемых безударных гласных в корне определяется по словарю.', '', 'Обратите внимание!!!', '', 'В заданиях ЕГЭ часто встречаются одинаковые слова, в которых пропущены разные гласные.', '', 'Одно слово может относиться к группе слов с непроверяемым гласным в корне или к группе слов с проверяемым гласным.', '', 'Сравните:', '', 'Г..ризонтальный - пропущена непроверяемая гласная.', '', 'Гориз..нтальный - пропущена проверяемая гласная корня, проверочное слово - горизОнт.', '', '', '4.Словарные слова (словарь слов с непроверяемыми гласными от ФИПИ)', 'абитуриент', 'абонемент', 'абрикос, абрикосовый', 'академия, академический', 'аквамарин', 'акварель, акварельный', 'аккомпанемент, аккомпанировать', 'аннотация', 'антресоли', 'аплодировать, аплодисменты', 'аппаратура', 'аппетит', 'аромат, ароматный', 'архитектор, архитектура', 'асфальт, асфальтировать', 'атмосфера, атмосферный', 'аттракцион', 'аукцион', 'багаж, багажный', 'багровый, багроветь, багряный', 'баланс, балансировать', 'балкон, балконный', 'барельеф', 'баскетбол, баскетбольный', 'бассейн']
